    status_t (*approve)(void *ctx, struct idl_txn idl_txn, uint32_t flags, uint64_t manifest_bytes, handle_t manifest, int32_t *out_verdict, uint32_t *out_programs, uint32_t *out_program, char *out_why, uint32_t *out_why_len);
